definition.script:
pipeline {
    agent any

    stages {
        stage('Generating Config Files') {
            steps {
                script{
                def configRuns = [:]
                for (int i = 1; i < 24; i++) {
                    def chrom_number = i
                    if (i == 23) {
                        chrom_number = 'X'
                    }
                    def consent_group_tag = ''
                    if (params.has_consent_group) {
                        consent_group_tag = '.' + params.study_consent_group
                    }
                    configRuns["configRuns${i}"] = {
                        build job: 'Genomic ETL - Create Configuration Files for EC2',
                parameters:
                [
                string(name: 'infrastructure_git_hash', value:params.infrastructure_git_hash),
                string(name: 'study_id', value:params.study_id),
                string(name: 'consent_group_tag', value:"${consent_group_tag}"),
                string(name: 'chrom_number', value:"${chrom_number}"),
                string(name: 'freeze_number', value:"${freeze_number}")
                ]
                    }
                }
                parallel configRuns
            }}
        }
        stage('Standing Up EC2s and Generating Annotated Files') {
            steps{
                script{
                def standupRuns = [:]
                for (int i = 1; i <24 ; i++) {
                    def chrom_number = i
                    if (i == 23) {
                        chrom_number = 'X'
                    }
                    def consent_group_tag = ''
                    if (params.has_consent_group) {
                        consent_group_tag = '.' + params.study_consent_group
                    }
                    standupRuns["standupRuns${i}"] = {
                        build job: 'Genomic ETL - Stand Up Nextflow EC2',
                parameters:
                [
                string(name: 'ROLE_ARN', value:params.ROLE_ARN),
                string(name: 'ami_id', value:params.ami_id),
                string(name: 'infrastructure_git_hash', value:params.infrastructure_git_hash),
                string(name: 'deployment_git_hash', value:params.deployment_git_hash),
                string(name: 'input_s3_account', value:params.input_s3_account),
                string(name: 'input_s3_bucket', value:params.input_s3_bucket),
                string(name: 'output_s3_bucket', value:params.output_s3_bucket),
                string(name: 'study_id', value:params.study_id),
                string(name: 'study_name', value:params.study_name),
                string(name: 'consent_group_tag', value:"${consent_group_tag}"),
                string(name: 'chrom_number', value:"${chrom_number}"),
                string(name: 'freeze_number', value:"${freeze_number}"),
                string(name: 'study_consent_group', value:params.study_consent_group),
                string(name: 'az', value:params.az),
                [$class: 'BooleanParameterValue', name: 'terminate_on_completion', value:params.terminate_on_completion]
                ]
                    }
                }
                parallel standupRuns
            }}
        }
    }


}
